BEGIN;
UPDATE public.config SET value='true' WHERE key='multi_tenant_enabled';
INSERT INTO auth.users(id,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data) VALUES('ce8f8da2-0e18-4200-bb52-977aac215332','inbound-rollback@example.invalid',now(),'{}','{}');
SELECT set_config('request.jwt.claims','{"sub":"ce8f8da2-0e18-4200-bb52-977aac215332","role":"authenticated"}',true);
SET LOCAL ROLE authenticated;
SELECT public.tenant_onboard('Canais teste rollback');
RESET ROLE;
SELECT set_config('request.jwt.claims',jsonb_build_object('sub','ce8f8da2-0e18-4200-bb52-977aac215332','role','authenticated','app_metadata',(SELECT raw_app_meta_data FROM auth.users WHERE id='ce8f8da2-0e18-4200-bb52-977aac215332'))::text,true);
DO $$ DECLARE tid uuid:=public.get_tenant_id();pid uuid;sid uuid;mid uuid;mid2 uuid;cid uuid:=gen_random_uuid();fid uuid:=gen_random_uuid();tok uuid;req uuid:=gen_random_uuid();r jsonb;c jsonb;payload jsonb:='{"contato":{"nome":"Teste Canal","email":"teste-canal@example.invalid"},"receita":12000}';did uuid; blocked boolean;BEGIN
 SELECT id INTO pid FROM public.sales_pipelines WHERE tenant_id=tid LIMIT 1;
 SELECT id INTO sid FROM public.sales_pipeline_stages WHERE pipeline_id=pid AND NOT is_won AND NOT is_lost ORDER BY position LIMIT 1;
 SELECT id INTO mid FROM public.team_members WHERE tenant_id=tid LIMIT 1;
 INSERT INTO public.team_members(tenant_id,name,email,role,team,is_active) VALUES(tid,'Segundo vendedor','segundo@example.invalid','comercial','comercial',true) RETURNING id INTO mid2;
 c:=public.inbound_admin('create',cid,'{"name":"Página Imersão"}');tok:=(c->>'token')::uuid;
 r:=public.inbound_receive(tok,req,payload);
 IF r->>'status'<>'captured' OR EXISTS(SELECT 1 FROM public.leads WHERE tenant_id=tid) THEN RAISE EXCEPTION 'Captura criou contato';END IF;
 r:=public.inbound_admin('field_create',fid,jsonb_build_object('pipeline_id',pid,'name','Faturamento mensal','type','number'));
 c:=public.inbound_admin('save',cid,jsonb_build_object('name','Página Imersão','pipeline_id',pid,'stage_id',sid,'method','round_robin','members',jsonb_build_array(mid,mid2),'mappings',jsonb_build_array(jsonb_build_object('source','contato.nome','target','name','required',true),jsonb_build_object('source','contato.email','target','email','required',true),jsonb_build_object('source','receita','target','custom:'||fid,'required',true))),1);
 r:=public.inbound_admin('preview',cid,payload);
 IF r->'mapped'->('custom:'||fid)<>'12000'::jsonb THEN RAISE EXCEPTION 'Número não mapeado';END IF;
 c:=public.inbound_admin('status',cid,'{"status":"active"}',(c->>'revision')::int);
 req:=gen_random_uuid();r:=public.inbound_receive(tok,req,payload);
 IF r->>'status'<>'processed' THEN RAISE EXCEPTION 'Recepção falhou: %',r;END IF;
 SELECT deal_id INTO did FROM crm_inbound.receipts WHERE id=(r->>'receipt_id')::uuid;
 IF NOT EXISTS(SELECT 1 FROM public.deals WHERE id=did AND sales_rep_id=mid AND metadata->'custom_fields'->fid::text='12000'::jsonb) THEN RAISE EXCEPTION 'Destino/valor/responsável incorreto';END IF;
 r:=public.inbound_receive(tok,req,payload);IF r->>'replayed'<>'true' THEN RAISE EXCEPTION 'Retry não deduplicou';END IF;
 r:=public.inbound_receive(tok,gen_random_uuid(),payload||'{"receita":15000}');
 IF r->>'status'<>'processed' OR (SELECT cursor FROM crm_inbound.channels WHERE id=cid)<>1 THEN RAISE EXCEPTION 'Reenvio consumiu rodízio';END IF;
 r:=public.inbound_receive(tok,gen_random_uuid(),'{"contato":{"nome":"Outro lead","email":"outro@example.invalid"},"receita":"20000"}');
 IF r->>'status'<>'processed' OR NOT EXISTS(SELECT 1 FROM crm_inbound.receipts WHERE id=(r->>'receipt_id')::uuid AND owner_id=mid2) THEN RAISE EXCEPTION 'Rodízio não alternou: %',r;END IF;
 r:=public.inbound_receive(tok,gen_random_uuid(),'{"contato":{"nome":"Inválido","email":"invalid@example.invalid"},"receita":"texto"}');
 IF r->>'status'<>'failed' OR EXISTS(SELECT 1 FROM public.leads WHERE tenant_id=tid AND email='invalid@example.invalid') THEN RAISE EXCEPTION 'Tipo inválido gerou registro parcial';END IF;
 IF (SELECT cursor FROM crm_inbound.channels WHERE id=cid)<>2 THEN RAISE EXCEPTION 'Falha avançou rodízio';END IF;
 blocked:=false;BEGIN PERFORM public.inbound_admin('get',gen_random_uuid());EXCEPTION WHEN insufficient_privilege THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Canal fora do tenant acessível';END IF;
 r:=public.inbound_admin('values',did);IF r->0->'value'<>'15000'::jsonb THEN RAISE EXCEPTION 'Campo não visível na oportunidade';END IF;
 c:=public.inbound_admin('status',cid,'{"status":"paused"}',(c->>'revision')::int);
 blocked:=false;BEGIN PERFORM public.inbound_receive(tok,gen_random_uuid(),payload);EXCEPTION WHEN no_data_found THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Pausado aceitou';END IF;
 IF has_function_privilege('anon','public.inbound_receive(uuid,uuid,jsonb)','EXECUTE') OR has_function_privilege('authenticated','public.inbound_receive(uuid,uuid,jsonb)','EXECUTE') THEN RAISE EXCEPTION 'RPC pública exposta';END IF;
END $$;
ROLLBACK;
